using MasrLab.Application.Common.Printing;
using Microsoft.EntityFrameworkCore;
namespace MasrLab.Infrastructure.Persistence.Readers;
public sealed class OperationalReportPrintDataReader(MasrLabDbContext db) : IOperationalReportDataReader
{ public async Task<OperationalReportPrintDto> ReadAsync(string name, DateTime from, DateTime to, int? id, CancellationToken ct=default) { var lines = name switch { PrintReportNames.WorkSheet => await db.WorkSheets.AsNoTracking().Where(x=>x.Period.Start>=from&&x.Period.Start<=to).Select(x=>new OperationalReportLineDto(x.Type.ToString(),x.PatientVisitIds??"",x.TestIds)).ToListAsync(ct), PrintReportNames.PatientHistory => await db.PatientVisits.AsNoTracking().Where(x=>x.VisitDate>=from&&x.VisitDate<=to&&(id==null||x.PatientId==id)).Select(x=>new OperationalReportLineDto(x.LabId,x.VisitDate.ToString(),x.Status.ToString())).ToListAsync(ct), PrintReportNames.Attendance => await db.AttendanceLogs.AsNoTracking().Where(x=>x.WorkPeriod.Start>=from&&x.WorkPeriod.Start<=to).Select(x=>new OperationalReportLineDto($"User {x.UserId}",x.WorkPeriod.Start.ToString(),x.Overtime.ToString())).ToListAsync(ct), PrintReportNames.PriceList => await db.PriceLists.AsNoTracking().Where(x=>id==null||x.Id==id).Select(x=>new OperationalReportLineDto(x.Name,x.IsDefault?"Default":"",x.PriceListItems.Count.ToString())).ToListAsync(ct), PrintReportNames.Drawer => await db.CashTransactions.AsNoTracking().Where(x=>x.TransactionDate>=from&&x.TransactionDate<=to).Select(x=>new OperationalReportLineDto(x.Type.ToString(),x.Amount.ToString("N2"),$"Account {x.AccountId}")).ToListAsync(ct), _ => await db.StatisticsSettings.AsNoTracking().Where(x=>x.IsEnabled).OrderBy(x=>x.DisplayOrder).Select(x=>new OperationalReportLineDto(x.DisplayName,x.TargetValue.HasValue?x.TargetValue.Value.ToString():"-",x.KpiCode.ToString())).ToListAsync(ct) }; return new OperationalReportPrintDto(name,from,to,lines); } }
